insert into site_texts(ns,key,value) values('t','v.ap','{"en":"Aras Metal products are made of galvanized steel. The material resists weather and chemicals, and it is fully recyclable at the end of its life.","de":"Die Produkte von Aras Metal bestehen aus verzinktem Stahl. Das Material widersteht Witterung und Chemikalien und ist am Ende seiner Lebensdauer vollständig recycelbar.","fr":"Les produits Aras Metal sont en acier galvanisé. Le matériau résiste aux intempéries et aux produits chimiques, et il est entièrement recyclable en fin de vie.","es":"Los productos de Aras Metal son de acero galvanizado. El material resiste la intemperie y los productos químicos, y es totalmente reciclable al final de su vida útil.","it":"I prodotti Aras Metal sono in acciaio zincato. Il materiale resiste agli agenti atmosferici e ai prodotti chimici ed è completamente riciclabile a fine vita.","tr":"Aras Metal ürünleri galvaniz çelikten yapılır. Malzeme hava koşullarına ve kimyasallara dayanır, ömrünü tamamlayınca tamamen geri dönüştürülür."}'::jsonb) on conflict do nothing;
