insert into site_texts(ns,key,value) values('meta','desc','{"en":"Since 1951 Aras Metal has made galvanized steel home, garden and tableware in Istanbul. The steel we use is 100% recyclable.","de":"Seit 1951 fertigt Aras Metal in Istanbul Haus-, Garten- und Tischwaren aus verzinktem Stahl. Der verwendete Stahl ist zu 100 % recycelbar.","fr":"Depuis 1951, Aras Metal fabrique à Istanbul des produits en acier galvanisé pour la maison, le jardin et la table. L''acier utilisé est recyclable à 100 %.","es":"Desde 1951, Aras Metal fabrica en Estambul productos de acero galvanizado para el hogar, el jardín y la mesa. El acero que utilizamos es 100 % reciclable.","it":"Dal 1951 Aras Metal produce a Istanbul articoli in acciaio zincato per la casa, il giardino e la tavola. L''acciaio che utilizziamo è riciclabile al 100%."}'::jsonb) on conflict do nothing;
